class LateInitializer(object):
    """
    On first access, class executes function passed in constructor and stores result for future use.
    Used to delay finding libraries used by robotframework until necessary
    """

    def __init__(self, expr):
        self.expr = expr
        self.value = None

    def __getattr__(self, item):
        if self.value is None:
            self.value = self.expr()
        return self.value.__getattribute__(item)


class ta5g_ue_measurements(object):
    def __init__(self):
        self.measurements_store = Store()
        self.wts_sim_lib = LateInitializer(lambda: BuiltIn().get_library_instance('ute_wtssim'))
        self.tshark_lib = LateInitializer(lambda: BuiltIn().get_library_instance('ute_tshark'))

    def _wait_for_tshark_message(interface, message):  # pylint: disable=no-self-argument
        def _wrap_function(f):
            def _run_method_and_wait_for_tshark_message(self, *args, **kwargs):
                tshark_alias = kwargs.pop('alias', 'wait_for_message')
                timeout = kwargs.pop('timeout', 5)
                self.tshark_lib.setup_tshark(interface=interface, alias=tshark_alias)
                try:
                    self.tshark_lib.start_counting_packets(packet_filter=message, alias=tshark_alias)
                    f(self, *args, **kwargs)
                    self.tshark_lib.wait_for_given_packets_number(packet_number=1, alias=tshark_alias, timeout=timeout)
                    self.tshark_lib.stop_counting_packets(alias=tshark_alias)
                finally:
                    self.tshark_lib.teardown_tshark(alias=tshark_alias)

            return _run_method_and_wait_for_tshark_message

        return _wrap_function

    def get_ue_measurement_configuration(self, ue_id, alias=None):
        """
        Get measurements active on ue and stores them under specified alias
        :param alias:
        :param ue_id:
        :return:
        """
        if self.measurements_store.has_alias(alias):
            self.measurements_store.remove(alias)
        self.measurements_store.add(Measurements(ue_id, self.wts_sim_lib), alias)

    def get_ue_measurements_count(self, alias=None):
        """
        Returns number of active measurements from measurement configuration stored under given alias.
        :param alias:
        :return:
        """
        return len(self.measurements_store.get(alias).meas_id_dict)

    def verify_that_measurement_configuration_has_frequencies_in_specified_order(self, frequencies, alias=None):
        """
        Checks if measurement configuration has frequencies in specified order
        in measurement configuration stored under given alias.
        Triggers, thresholds and other configuration details are not taken into account.
        :param alias:
        :param frequencies: List of single rfcns or list of possible rfcns
        :return:
        """
        Verifications.verify_that_measurement_configuration_has_frequencies_in_specified_order(
            self.measurements_store.get(alias).get_frequencies_order(), frequencies
        )

    def verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_thresholds(
        self, event_type, event_params, frequencies, alias=None
    ):
        """
        Checks measurement configuration stored under given alias if events are active on given
        frequencies and if they have specific thresholds
        :param alias:
        :param event_type: Measurement (event) type. Accepts single/multiple values, eg.:
        event_type='EventA3'
        event_type='EventB2'
        event_type=['EventA3', 'EventA5']
        :param event_params: Dictionary containing event parameters, eg. {'Threshold': 'RSRP 35'}
        :param event_params: Dictionary containing event parameters, eg. {'Threshold': 'RSRP 35'}
        Detailed report configuration parameters are different for almost every event
        :param frequencies: List of frequencies on which given events should be active
        :return:
        """
        if not isinstance(frequencies, list):
            frequencies = [frequencies]
        Verifications.verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_thresholds(
            self.measurements_store.get(alias), event_type, event_params, frequencies
        )

    def verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_trigger(
        self, event_type, trigger, frequencies, alias=None
    ):
        """
        Checks measurement configuration stored under given alias if events are active on given
        frequencies and if they have specific trigger
        :param alias:
        :param event_type: Measurement (event) type. Accepts single/multiple values, eg.:
        event_type='EventA3'
        event_type='EventB2'
        event_type=['EventA3', 'EventA5']
        :param trigger:
        :param frequencies: List of frequencies on which given events should be active
        :return:
        """
        if not isinstance(frequencies, list):
            frequencies = [frequencies]
        Verifications.verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_trigger(
            self.measurements_store.get(alias), event_type, trigger, frequencies
        )

    def verify_that_specified_events_are_not_active_on_given_frequencies_with_specified_trigger(
        self, event_type, trigger, frequencies, alias=None
    ):
        """
        Checks if event is inactive on given frequencies with the given trigger
        :param event_type: Measurement (event) type. Single or multiple values are accepted, eg.:\
        event_type='EventB2'\
        event_type=['EventA1','EventB2']\
        :param trigger: Reference Signal Received measurement type for the event(s)
        trigger='rspq'
        :param frequencies: Frequency or list of frequencies on which given events
        should be inactive, accepts signle frequency, \
        eg. [2100, 2200], [300], 1200
        :param alias: to get stored measurement configuration on the same alias
        """
        try:
            if not isinstance(frequencies, list):
                frequencies = [frequencies]
            Verifications.verify_that_specified_events_are_active_on_given_frequencies_and_have_specified_trigger(
                self.measurements_store.get(alias), event_type, trigger, frequencies
            )
        except EventNotFoundException:
            pass
        else:
            raise AssertionError(
                "Matching measurement found for event {} with trigger {} and frequency {}".format(
                    event_type, trigger, frequencies
                )
            )

    def verify_that_specified_events_are_active_on_given_frequencies(self, event_list, frequencies, alias=None):
        """
        Checks measurement configuration stored under given alias if given events are active on given frequencies
        :param alias:
        :param event_list: List of events that should be active eg. ["EventA3", "EventA5"].
                           Accepts single event string.
        :param frequencies: List of frequencies on which given events should be active,
        accepts single frequency. Eg. [2100, 2200], [300], 1200
        :return:
        """
        if not isinstance(frequencies, list):
            frequencies = [frequencies]
        Verifications.verify_that_specified_events_are_active_on_given_frequencies(
            self.measurements_store.get(alias), event_list, frequencies
        )

