    def send_ue_measurement_nr_event_A1_scell_addition_with_aligned_meas_id(self, ue_id, trigger_type='RSRP', pcell_id='1',
                                                                            scellTechnology='FDD', alias=None, timeout=5, pass_regexp=None,
                                                                            get_ue_meas_cfg=None, **kwargs):
        """
        Sending UE Measurements for A1 Event regarding SCell Addition on given PCell with aligned meas_id
        :param alias:
        :param ue_id:
        :param trigger_type: 'RSRP' or 'RSRQ'
        :param pcell_id: New Radio Cell instance identifier (nrCellId) of PCell
        :param scellTechnology: 'TDD' or 'FDD' cellTechnology, important only in case of RSRP trigger type,
        based on this parameter a1ThresholdSCellAddSsbRsrpTDD (scellTechnology='TDD')
        or a1ThresholdSCellAddSsbRsrpFDD (scellTechnology='FDD') is taken as a trigger condition for SCell Addition
        :param timeout:
        :param pass_regexp:
        :param get_ue_meas_cfg: (Optional) get measurements active on ue and display it before sending measurement
        :param kwargs: other arguments necessary for ue_measurement_send_nr, except id, event and meas_id
        (id, event, meas_id parameters set automatically)
        Be aware that function doesn't check if Your parameters are correct
        :return:
        """
        meas_id = self.get_meas_id_for_A1_scell_addition(ue_id=ue_id, trigger_type=trigger_type, pcell_id=pcell_id,
                                                         scellTechnology=scellTechnology, alias=alias)
        self.send_ue_measurement_nr_for_specific_event(ue_id=ue_id, meas_id=meas_id, event='A1', timeout=timeout,
                                                       pass_regexp=pass_regexp, get_ue_meas_cfg=get_ue_meas_cfg, **kwargs)

