    def send_ue_measurement_nr(
        self,
        ue_id,
        meas_id,
        nrs_result=None,
        index=None,
        event=None,
        phycell_id=None,
        nrsrp_nr=None,
        srsrp_nr=None,
        timeout=5,
        pass_regexp=None,
        get_ue_meas_cfg=None,
        **kwargs
    ):
        """
        :param timeout:
        :param pass_regexp:
        :param get_ue_meas_cfg: (Optional) get measurements active on ue and display it before sending measurement
        :param ue_id: Specified UE ID
        :param meas_id: measurement identity
        :param index: SSB-Index or CSI-RS-Index depending on the indi
               cated rsType. If rsType is SSB, valid value is from 0..63 only
        :param nrs_result: (Optional) RSRP:RSRQ:SINR values for neighbor cells RS Result in NR
        :param event: (Optional) event type
        :param srsrp_nr: (Optional) RSRP value for serving cell in NR
        :param srsrq_nr: (Optional) RSRQ value for serving cell in NR
        :param ssinr_nr: (Optional) SINR value for serving cell in NR
        :param srs_result: (Optional) Beam measurement quantity results of serving cell.
        :param phycell_id: (Optional) physical cell id. Multiple neighbors maybe
               specified by grouping according to phycell_id
        :param nrsrp_nr: (Optional) RSRP value for neighbor cell(s) in NR
        :param nrsrq_nr: (Optional) RSRQ value for neighbor cell(s) in NR
        :param nsinr_nr: (Optional) SINR value for neighbor cell(s) in NR
        :param rs_type: (Optional) Reference signal to be measured and reported: ssb (SS/PBCH block) or CSI-RS
        """
        if get_ue_meas_cfg:
            try:
                self.get_ue_measurement_configuration(ue_id, alias=None)
            except Exception:
                BuiltIn().log_to_console("UE Measurement Configuration for UE_ID:{} not found".format(ue_id))
        arguments = " ".join(["{}={}".format(key, value) for key, value in kwargs.items()])
        self.wts_sim_lib.execute_egate_command(
            cmd="ue_measurement_send_nr id={} meas_id={} {} {} {} {} {} {} ".format(
                ue_id,
                meas_id,
                "index=" + str(index) if index else "",
                "nrs_result=" + str(nrs_result) if nrs_result else "",
                "event=" + str(event) if event else "",
                "phycell_id=" + str(phycell_id) if phycell_id else "",
                "nrsrp_nr=" + str(nrsrp_nr) if nrsrp_nr else "",
                "srsrp_nr=" + str(srsrp_nr) if srsrp_nr else "",
            )
            + arguments,
            pass_regexp=pass_regexp,
            timeout=timeout,
        )

    def send_custom_ue_measurement_nr(self, *args):  # noqa: C901
        """
        :param pass_regexp: (optional) Regexp to wait for after sending measurement
        :param timeout: (optional) timeout for egate command
        :param get_ue_meas_cfg: (optional) get measurements active on ue and display it before sending measurement
        :param args: args are indefinite positional arguments - to make measurement works You have to pass all
        needed parameters as string, like "id=1". Be aware that function doesn't check if Your parameters are correct,
        You should use it only in cases when it's not possible to use "send_ue_measurement_nr"

        """
        timeout_string = "timeout="
        pass_regexp_string = "pass_regexp="
        get_ue_meas_cfg_string = "get_ue_meas_cfg="
        ue_id = None
        timeout = None
        pass_regexp = None
        get_ue_meas_cfg = None
        arguments = ""
        for arg in args:
            if timeout_string in arg:
                timeout = arg.replace(timeout_string, '')
            elif pass_regexp_string in arg:
                pass_regexp = arg.replace(pass_regexp_string, '')
            elif get_ue_meas_cfg_string in arg:
                get_ue_meas_cfg = arg.replace(get_ue_meas_cfg_string, '')
            else:
                arguments += arg + " "
        if get_ue_meas_cfg:
            try:
                pattern = re.compile(r'\bid=\d+\b')
                ue_id = pattern.findall(arguments)[0].split("=")[-1]
                self.get_ue_measurement_configuration(ue_id, alias=None)
            except Exception:
                BuiltIn().log_to_console("UE Measurement Configuration for UE_ID:{} not found".format(ue_id))
        self.wts_sim_lib.execute_egate_command(
            cmd="ue_measurement_send_nr {}".format(arguments),
            pass_regexp=pass_regexp,
            timeout=timeout,
        )

    def send_single_measurement_report_multiple_times(
        self, ue_id, meas_id, srsrp, nrsrp, srsrq, nrsrq, phycell_id, ecgi, no_times_to_repeat, meas_interval
    ):
        """

        :param ue_id:
        :param meas_id:
        :param srsrp:
        :param nrsrp:
        :param srsrq:
        :param nrsrq:
        :param phycell_id:
        :param ecgi:
        :param no_times_to_repeat:
        :param meas_interval:
        :return:
        """
        BuiltIn().log_to_console(
            "Sending UE {} measurements {} times with interval {}: meas_id={} srsrp={} srsrq={}"
            "phycell_id={} nrsrp={} nrsrq={} for neighbour cell ecgi={}".format(
                ue_id, no_times_to_repeat, meas_interval, meas_id, srsrp, srsrq, phycell_id, nrsrp, nrsrq, ecgi
            )
        )
        for _ in range(int(no_times_to_repeat)):
            self.send_ue_measurement(
                ue_id=ue_id,
                meas_id=meas_id,
                srsrp=srsrp,
                nrsrp=nrsrp,
                srsrq=srsrq,
                nrsrq=nrsrq,
                phycell_id=phycell_id,
                ecgi=ecgi,
            )
            time.sleep(float(meas_interval))

    def send_ue_measurement_by_meas_id(self, ue_id, meas_id, measurement):
        """

        :param ue_id:
        :param meas_id:
        :param measurement:
        :return:
        """
        self.wts_sim_lib.execute_egate_command(
            cmd="ue_measurement_send id={} meas_id={} {}".format(ue_id, meas_id, measurement)
        )

    def send_ue_measurement_by_meas_id_multiple_times(self, ue_id, meas_id, measurement, repetition, interval=0.5):
        """

        :param ue_id:
        :param meas_id:
        :param measurement:
        :param repetition:
        :param interval:
        :return:
        """
        for _ in range(int(repetition)):
            self.send_ue_measurement_by_meas_id(ue_id=ue_id, meas_id=meas_id, measurement=measurement)
            time.sleep(float(interval))

    def send_ue_measurement_by_meas_id_for_multiple_ues(self, ue_id_list, meas_id, measurement, interval=0.3):
        """

        :param ue_id_list:
        :param meas_id:
        :param measurement:
        :param interval:
        :return:
        """
        BuiltIn().log_to_console(
            "Sending UE measurements to {} UEs with interval {}: meas_id={} {}".format(
                len(ue_id_list), interval, meas_id, measurement
            )
        )
        for ue_id in ue_id_list:
            self.send_ue_measurement_by_meas_id(ue_id=ue_id, meas_id=meas_id, measurement=measurement)
            time.sleep(float(interval))

    def send_ue_measurement_by_meas_id_for_multiple_ues_multiple_times(
        self, ue_id_list, meas_id, measurement, repetition, interval_for_every_ue=0.3, overall_loop_interval=1
    ):
        """
        ${interval_for_every_ue} configure interval of sending measurements between every Ue
        ${repetition} configure how many times sending measurements is repeated for group of configured ue list
        ${overall_loop_interval} configure interval between every group of configured ue list
        :param ue_id_list:
        :param meas_id:
        :param measurement:
        :param repetition:
        :param interval_for_every_ue:
        :param overall_loop_interval:
        :return:
        """
        for _ in range(int(repetition)):
            self.send_ue_measurement_by_meas_id_for_multiple_ues(
                ue_id_list=ue_id_list, meas_id=meas_id, measurement=measurement, interval=interval_for_every_ue
            )
            time.sleep(float(overall_loop_interval))

