    @_wait_for_tshark_message(interface=INTERFACE_UU, message=RRC_CONNECTION_RECONFIGURATION_COMPLETE)
    def send_measurement_response_and_wait_for_rrc_connection_reconfiguration(
        self, ue_id, event_type, earfcn, measurement, trigger='rsrp'
    ):
        """
        Sends measurement response with given type, trigger and rfcn to matching measurement id
        and waits until rrc connection reconfiguration completes
        :param ue_id:
        :param event_type: Measurement (event) type. Accepts single/multiple values, eg.:
        event_type='EventA3'
        event_type='EventB2'
        event_type=['EventA3', 'EventA5']
        :param earfcn: Carrier frequency included in measurement report.
        :param measurement: Any combination of egate measurement parameters which are injected directly
            into ue_measurement_send command, eg.:
        measurement='srsrp=25'
        measurement='srsrq=10 srsrp=20'
        measurement='srsrp=10 nrsrp=20 srsrq=5 nrsrq=10'
        :param trigger: Trigger of given measurement (event). Can be 'rsrp' or 'rsrq'. Case insensitive.
        :param timeout: wait for message decorator argument: default 5s
        :param alias: wait for message decorator argument: default "wait_for_message"
        :return:
        """
        self.get_ue_measurement_configuration(ue_id)
        meas_id = self.get_meas_id_for_measurement_on_frequency(event_type, earfcn, trigger=trigger.lower())
        self.send_ue_measurement_by_meas_id(ue_id, meas_id, measurement)

