    @_wait_for_tshark_message(interface=INTERFACE_UU, message=RRC_HANDOVER_TO_HRPD)
    def send_b2_measurement_with_specified_trigger_and_wait_for_handover_to_hrpd(
        self, ue_id, arfcn, measurement, trigger
    ):
        """
        Sends B2 measurement report by meas id and waits for RRC message - handover to cdma2000-hrpd
        As a precondition for succesful handover cdma2000 preregistaration must be done for UE
        :param ue_id:
        :param measurement: measurement string with values of serving lte cell,
            Cdma2000 physical id pilot strength and phase values
        :param arfcn: frequency of the cdma2000 cell
        :param trigger: rsrp or rsrq
        :return:
        """
        self.wts_sim_lib.execute_egate_command(
            cmd="preregister_ue_cdma2000 id={} hrpd=yes".format(ue_id),
            pass_regexp="HRPD preregistration completed",
            timeout=9,
        )
        self.get_ue_measurement_configuration(ue_id)
        meas_id = self.get_meas_id_for_measurement_on_frequency(
            event_type='EventB2', carrier_freq=arfcn, trigger=trigger.lower()
        )
        self.send_ue_measurement_by_meas_id(ue_id, meas_id, measurement)

